/** One merged `AppButton` look (base, state, size): colours are role keys, sizes pt/dp. */
data class ButtonAppearance(
    val backgroundColor: AppColorRole?,
    val textColor: AppColorRole,
    val borderColor: AppColorRole?,
    val spinnerColor: AppColorRole?,
    val overlayColor: AppColorRole?,
    val borderWidth: Double?,
    val typography: AppTextStyle,
    val rounded: Double,
    val height: Double,
    val paddingTop: Double,
    val paddingEnd: Double,
    val paddingBottom: Double,
    val paddingStart: Double,
    val iconSize: AppIconSize,
    val iconGap: Double,
    val focusRing: FocusRingTokens?,
)

/** An allowed `AppButton` combination and its merged look. */
data class ButtonLook(
    val variant: ButtonVariant,
    val size: ButtonSize,
    val state: ButtonState,
    val appearance: ButtonAppearance,
)

/** Every allowed `AppButton` combination and its look, per context; each context in a holder. */
data class ButtonSpec(
    val looks: List<ButtonLook>,
) {
    /** The merged look of an allowed combination; none when the contract does not allow it. */
    fun appearance(
        variant: ButtonVariant,
        size: ButtonSize,
        state: ButtonState,
    ): ButtonAppearance? =
        looks.firstOrNull { it.variant == variant && it.size == size && it.state == state }?.appearance

