/** One `AppButton` gallery cell and its test ID. */
data class ButtonGalleryEntry(
    val variant: ButtonVariant,
    val size: ButtonSize,
    val state: ButtonState,
    val testId: String,
)

/** Variants of `AppChip` (chip.yaml, board C03), each with its contract id. */
enum class ChipVariant(
    val id: String,
    val role: ChipRole,
    val parts: List<ChipPart>,
) {
    WEATHER("weather", ChipRole.BUTTON, emptyList()),
    CONTEXT("context", ChipRole.BUTTON, emptyList()),
    CONDITION_SUNNY("condition-sunny", ChipRole.BUTTON, emptyList()),
    CONDITION_RAIN("condition-rain", ChipRole.BUTTON, emptyList()),
    CONDITION_COLD("condition-cold", ChipRole.BUTTON, emptyList()),
    CONDITION_HOT("condition-hot", ChipRole.BUTTON, emptyList()),
    CONDITION_WINDY("condition-windy", ChipRole.BUTTON, emptyList()),
    CONDITION_SNOW("condition-snow", ChipRole.BUTTON, emptyList()),
    CONDITION_EVENING("condition-evening", ChipRole.BUTTON, emptyList()),
    OVERRIDE("override", ChipRole.BUTTON, listOf(ChipPart.DETAIL)),
    REASON("reason", ChipRole.DISCLOSURE, emptyList()),
    CHOICE("choice", ChipRole.SELECTABLE, emptyList()),
    SWATCH("swatch", ChipRole.SELECTABLE, listOf(ChipPart.SWATCH)),
    FILTER("filter", ChipRole.SELECTABLE, listOf(ChipPart.DETAIL)),
    FILTER_MENU("filter-menu", ChipRole.MENU, emptyList()),
    GROUP_SORT("group-sort", ChipRole.MENU, listOf(ChipPart.PREFIX)),
    NEVER_SUGGEST("never-suggest", ChipRole.BUTTON, emptyList()),
    SOFT_DISLIKE("soft-dislike", ChipRole.BUTTON, emptyList()),
    ADD("add", ChipRole.BUTTON, emptyList()),
    NEVER_SUGGEST_ADD("never-suggest-add", ChipRole.BUTTON, emptyList()),
}

/** Sizes of `AppChip` (chip.yaml, board C03), each with its contract id. */
enum class ChipSize(
    val id: String,
) {
    COMPACT("compact"),
    SMALL("small"),
    MEDIUM("medium"),
    LARGE("large"),
}

/** States of `AppChip` (chip.yaml, board C03), each with its contract id. */
enum class ChipState(
    val id: String,
) {
    ENABLED("enabled"),
    PRESSED("pressed"),
    FOCUSED("focused"),
    DISABLED("disabled"),
    SELECTED("selected"),
    SELECTED_PRESSED("selected-pressed"),
    SELECTED_FOCUSED("selected-focused"),
    SELECTED_DISABLED("selected-disabled"),
    EXPANDED("expanded"),
    EXPANDED_PRESSED("expanded-pressed"),
    EXPANDED_FOCUSED("expanded-focused"),
}

/** Accessibility roles of `AppChip` (chip.yaml, board C03), each with its contract id. */
enum class ChipRole(
    val id: String,
) {
    BUTTON("button"),
    SELECTABLE("selectable"),
    DISCLOSURE("disclosure"),
    MENU("menu"),
}

/** Values of the `selection` prop of `AppChip` (chip.yaml, board C03). */
enum class ChipSelection(
    val id: String,
) {
    MULTIPLE("multiple"),
    SINGLE("single"),
}

/** Part kinds of `AppChip` (chip.yaml, board C03), each with its contract id. */
enum class ChipPartKind(
    val id: String,
) {
    TEXT("text"),
    SWATCH("swatch"),
}

/** Part positions of `AppChip` (chip.yaml, board C03), each with its contract id. */
enum class ChipPartPosition(
    val id: String,
) {
    BEFORE_LABEL("before-label"),
    AFTER_LABEL("after-label"),
}

/** Parts of `AppChip` beside its label (chip.yaml `parts`), in contract order. */
enum class ChipPart(
    val id: String,
    val kind: ChipPartKind,
    val position: ChipPartPosition,
    val separatorKey: String?,
    val takesLeadingIcon: Boolean,
) {
    PREFIX("prefix", ChipPartKind.TEXT, ChipPartPosition.BEFORE_LABEL, null, false),
    SWATCH("swatch", ChipPartKind.SWATCH, ChipPartPosition.BEFORE_LABEL, null, false),
    DETAIL("detail", ChipPartKind.TEXT, ChipPartPosition.AFTER_LABEL, "ds_chip_detail_separator", false),
}

/** Where an icon of `AppChip` comes from: a glyph of the icon set, or the caller's prop. */
sealed interface ChipIconSource {
    /** A glyph of the icon set (`AppIconName`). */
    data class Glyph(
        val name: AppIconName,
    ) : ChipIconSource

    /** The caller's icon prop. */
    data object Prop : ChipIconSource
}

