/** Glyph sets of `AppIcon` (icon.yaml, board C02), in first-appearance order. */
enum class AppIconSet(
    val id: String,
) {
    NAVIGATION("navigation"),
    ACTIONS("actions"),
    WEATHER("weather"),
    CLOSET("closet"),
    STATUS("status"),
    ACCOUNT("account"),
    CAPTURE("capture"),
}

/** The icon scale of `AppIcon` (icon.yaml, board C02): each step a DESIGN.md `components.icon-<step>` token. */
enum class AppIconSize(
    val id: String,
    val size: Double,
    val strokeWidth: Double,
) {
    XS("icon-xs", 12.0, 2.2),
    SM("icon-sm", 16.0, 1.7),
    MD("icon-md", 20.0, 1.7),
    LG("icon-lg", 24.0, 1.7),
    XL("icon-xl", 32.0, 1.7),
    HERO("icon-hero", 56.0, 1.7),
}

/** The viewBox every AppIcon glyph is drawn in, and the default size. */
object AppIconMetrics {
    val viewBox: Double = 24.0
    val defaultSize: AppIconSize = AppIconSize.LG
}

/** One AppIcon glyph: its shapes, painted in order. */
data class AppIconGlyph(
    val shapes: List<AppIconShape>,
)

/** One path of a glyph and how it is painted, in viewBox units. */
data class AppIconShape(
    val paint: AppIconPaint,
    val segments: List<AppIconSegment>,
)

/** How a shape is painted: stroked, filled, or both. */
enum class AppIconPaint(
    val id: String,
) {
    STROKE("stroke"),
    FILL("fill"),
    BOTH("both"),
}

/** One absolute path command; points are x, y pairs: 1 (move, line), 3 (cubic), 0 (close). */
data class AppIconSegment(
    val command: AppIconCommand,
    val points: List<Double>,
)

/** The path commands a compiled glyph uses. */
enum class AppIconCommand(
    val id: String,
) {
    MOVE("move"),
    LINE("line"),
    CUBIC("cubic"),
    CLOSE("close"),
}

/** Variants of `AppReasonRow` (reason-row.yaml, board C03), each with its contract id. */
enum class ReasonRowVariant(
    val id: String,
    val role: ReasonRowRole,
    val parts: List<ReasonRowPart>,
) {
    STANDARD("standard", ReasonRowRole.REGION, listOf(ReasonRowPart.FACT, ReasonRowPart.FRESHNESS)),
}

/** Sizes of `AppReasonRow` (reason-row.yaml, board C03), each with its contract id. */
enum class ReasonRowSize(
    val id: String,
) {
    STANDARD("standard"),
}

/** States of `AppReasonRow` (reason-row.yaml, board C03), each with its contract id. */
enum class ReasonRowState(
    val id: String,
) {
    ENABLED("enabled"),
}

/** Accessibility roles of `AppReasonRow` (reason-row.yaml, board C03), each with its contract id. */
enum class ReasonRowRole(
    val id: String,
) {
    REGION("region"),
}

/** Part kinds of `AppReasonRow` (reason-row.yaml, board C03), each with its contract id. */
enum class ReasonRowPartKind(
    val id: String,
) {
    TEXT("text"),
}

/** Part positions of `AppReasonRow` (reason-row.yaml, board C03), each with its contract id. */
enum class ReasonRowPartPosition(
    val id: String,
) {
    LINE("line"),
}

/** Parts of `AppReasonRow` beside its label (reason-row.yaml `parts`), in contract order. */
enum class ReasonRowPart(
    val id: String,
    val kind: ReasonRowPartKind,
    val position: ReasonRowPartPosition,
    val separatorKey: String?,
    val takesLeadingIcon: Boolean,
) {
    FACT("fact", ReasonRowPartKind.TEXT, ReasonRowPartPosition.LINE, null, true),
    FRESHNESS("freshness", ReasonRowPartKind.TEXT, ReasonRowPartPosition.LINE, null, false),
}

/** Where an icon of `AppReasonRow` comes from: a glyph of the icon set, or the caller's prop. */
sealed interface ReasonRowIconSource {
    /** A glyph of the icon set (`AppIconName`). */
    data class Glyph(
        val name: AppIconName,
    ) : ReasonRowIconSource

    /** The caller's icon prop. */
    data object Prop : ReasonRowIconSource
}

/** Test IDs of `AppReasonRow`: the iOS accessibilityIdentifier and the Android testTag. */
object ReasonRowTestId {
    val standardStandardEnabled: String = "ds-reason-row-standard-standard-enabled"
}

/** One merged `AppReasonRow` look (base, state, size): colours are role keys, sizes pt/dp. */
data class ReasonRowAppearance(
    val backgroundColor: AppColorRole,
    val textColor: AppColorRole,
    val borderColor: AppColorRole,
    val iconColor: AppColorRole,
    val iconDiscColor: AppColorRole,
    val factColor: AppColorRole,
    val freshnessColor: AppColorRole,
    val borderWidth: Double,
    val typography: AppTextStyle,
    val rounded: Double,
    val paddingTop: Double,
    val paddingEnd: Double,
    val paddingBottom: Double,
    val paddingStart: Double,
    val lineGap: Double,
    val iconDiscSize: Double,
    val factTypography: AppTextStyle,
    val freshnessTypography: AppTextStyle,
    val iconSize: AppIconSize,
    val iconGap: Double,
    val leadingIcon: ReasonRowIconSource,
)

/** An allowed `AppReasonRow` combination and its merged look. */
data class ReasonRowLook(
    val variant: ReasonRowVariant,
    val size: ReasonRowSize,
    val state: ReasonRowState,
    val appearance: ReasonRowAppearance,
)

