/** One `AppReasonRow` gallery cell and its test ID. */
data class ReasonRowGalleryEntry(
    val variant: ReasonRowVariant,
    val size: ReasonRowSize,
    val state: ReasonRowState,
    val testId: String,
)

/** Variants of `AppTag` (tag.yaml, board C03), each with its contract id. */
enum class TagVariant(
    val id: String,
    val role: TagRole,
    val parts: List<TagPart>,
) {
    PLAN_FREE("plan-free", TagRole.TEXT, emptyList()),
    PLAN_ESSENTIALS("plan-essentials", TagRole.TEXT, emptyList()),
    PLAN_PLUS("plan-plus", TagRole.TEXT, emptyList()),
    PLAN_PRO("plan-pro", TagRole.TEXT, emptyList()),
    LOCK("lock", TagRole.TEXT, emptyList()),
    LATER("later", TagRole.TEXT, emptyList()),
    PROVISIONAL("provisional", TagRole.TEXT, emptyList()),
    NEW("new", TagRole.TEXT, listOf(TagPart.DOT)),
    AVAILABLE("available", TagRole.TEXT, emptyList()),
    UNAVAILABLE("unavailable", TagRole.TEXT, emptyList()),
    DIFFERS("differs", TagRole.TEXT, emptyList()),
    KIND("kind", TagRole.TEXT, emptyList()),
}

/** Sizes of `AppTag` (tag.yaml, board C03), each with its contract id. */
enum class TagSize(
    val id: String,
) {
    SMALL("small"),
    REGULAR("regular"),
}

/** States of `AppTag` (tag.yaml, board C03), each with its contract id. */
enum class TagState(
    val id: String,
) {
    ENABLED("enabled"),
}

/** Accessibility roles of `AppTag` (tag.yaml, board C03), each with its contract id. */
enum class TagRole(
    val id: String,
) {
    TEXT("text"),
}

/** Part kinds of `AppTag` (tag.yaml, board C03), each with its contract id. */
enum class TagPartKind(
    val id: String,
) {
    DOT("dot"),
}

/** Part positions of `AppTag` (tag.yaml, board C03), each with its contract id. */
enum class TagPartPosition(
    val id: String,
) {
    BEFORE_LABEL("before-label"),
}

/** Parts of `AppTag` beside its label (tag.yaml `parts`), in contract order. */
enum class TagPart(
    val id: String,
    val kind: TagPartKind,
    val position: TagPartPosition,
    val separatorKey: String?,
    val takesLeadingIcon: Boolean,
) {
    DOT("dot", TagPartKind.DOT, TagPartPosition.BEFORE_LABEL, null, false),
}

/** Where an icon of `AppTag` comes from: a glyph of the icon set, or the caller's prop. */
sealed interface TagIconSource {
    /** A glyph of the icon set (`AppIconName`). */
    data class Glyph(
        val name: AppIconName,
    ) : TagIconSource

    /** The caller's icon prop. */
    data object Prop : TagIconSource
}

/** Test IDs of `AppTag`: the iOS accessibilityIdentifier and the Android testTag. */
object TagTestId {
    val planFreeRegularEnabled: String = "ds-tag-plan-free-regular-enabled"
