    val newRegularEnabled: String = "ds-tag-new-regular-enabled"
    val availableRegularEnabled: String = "ds-tag-available-regular-enabled"
    val unavailableRegularEnabled: String = "ds-tag-unavailable-regular-enabled"
    val differsSmallEnabled: String = "ds-tag-differs-small-enabled"
    val kindRegularEnabled: String = "ds-tag-kind-regular-enabled"
}

/** One merged `AppTag` look (base, state, size): colours are role keys, sizes pt/dp. */
data class TagAppearance(
    val backgroundColor: AppColorRole?,
    val textColor: AppColorRole,
    val borderColor: AppColorRole?,
    val borderWidth: Double?,
    val typography: AppTextStyle,
    val rounded: Double,
    val height: Double,
    val paddingTop: Double,
    val paddingEnd: Double,
    val paddingBottom: Double,
    val paddingStart: Double,
    val iconSize: AppIconSize?,
    val iconGap: Double?,
    val borderDash: Double?,
    val dotSize: Double?,
    val dotGap: Double?,
    val leadingIcon: TagIconSource?,
)

/** An allowed `AppTag` combination and its merged look. */
data class TagLook(
    val variant: TagVariant,
    val size: TagSize,
    val state: TagState,
    val appearance: TagAppearance,
)

