/** One `AppTag` gallery cell and its test ID. */
data class TagGalleryEntry(
    val variant: TagVariant,
    val size: TagSize,
    val state: TagState,
    val testId: String,
)

/** The gallery sections of the components, in board order, each with its contract id. */
enum class GalleryComponent(
    val id: String,
    val title: String,
    val slug: String,
) {
    BUTTON("button", "C01 Buttons", "c01-buttons"),
    ICON("icon", "C02 Icons", "c02-icons"),
    BADGE("badge", "C03 Badges", "c03-badges"),
    CHIP("chip", "C03 Chips", "c03-chips"),
    REASON_ROW("reason-row", "C03 Reason row", "c03-reason-row"),
    TAG("tag", "C03 Tags", "c03-tags"),
}

